"""
生成完整的 DLT645-2007 DI 映射表
"""
import json

def generate_di_map():
    di_map = {}

    # 电能量数据类 (00)
    # 正向有功电能
    for i in range(16):  # 费率 0-15
        di_key = f"0001{i:02X}00"
        if i == 0:
            name = "当前正向有功总电能"
        else:
            name = f"当前正向有功费率{i}电能"
        di_map[di_key] = {"name": name, "unit": "kWh", "data_type": "XXXXXX.XX", "length": 4}

    # 反向有功电能
    for i in range(16):
        di_key = f"0002{i:02X}00"
        if i == 0:
