            0x7bc7, 0x6a4e, 0x58d5, 0x495c, 0x3de3, 0x2c6a, 0x1ef1, 0x0f78
        ]
        fcs = 0xFFFF
        for byte in data:
            fcs = ((fcs >> 8) ^ crc_table[(fcs ^ byte) & 0xFF]) & 0xFFFF
        return fcs ^ 0xFFFF
